--
-- Table structure for table `textositinerarios`
--

DROP TABLE IF EXISTS `textositinerarios`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `textositinerarios` (
  `id` int NOT NULL AUTO_INCREMENT,
  `num_dia` int NOT NULL,
  `texto_dia` longtext NOT NULL,
  `id_itinerario` int DEFAULT NULL,
  `titulo_dia` longtext NOT NULL,
  PRIMARY KEY (`id`),
  KEY `id_itinerario_idx` (`id_itinerario`)
) ENGINE=InnoDB AUTO_INCREMENT=54 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

